const fs = require('fs');
fs.writeFileSync(
  'dist/shared/diagnostic-context.js',
  '// Generated by tools/sync-diagnostics.cjs.\n' +
    fs
      .readFileSync('miniprogram/services/diagnostic-context.js', 'utf8')
      .replace(
        'module.exports={diagnosticContext,fingerprint};',
        'export {diagnosticContext,fingerprint};',
      )
      .replace(
        'module.exports = { diagnosticContext, fingerprint };',
        'export { diagnosticContext, fingerprint };',
      ),
);
